async function withSchema(schema: string, run: (conn: mysql.Connection) => Promise<void>): Promise<void> {
  const host = process.env.MYSQL_REFERENCE_HOST
  const db = host === undefined ? await MySQL.open(':memory:') : undefined
  const conn = await mysql.createConnection(db === undefined
    ? { host: host ?? '127.0.0.1', port: Number(process.env.MYSQL_REFERENCE_PORT ?? 3306), user: 'root', password: process.env.MYSQL_REFERENCE_PASSWORD ?? 'root' }
    : { stream: db.createStream(), user: 'root' })
  try {
    await conn.query(`CREATE DATABASE ${schema}`)
    await conn.query(`USE ${schema}`)
    await run(conn)
  } finally { await conn.query(`DROP DATABASE IF EXISTS ${schema}`); await conn.end(); await db?.end() }
}

async function execution(conn: mysql.Connection, statement: mysql.PreparedStatementInfo, entry: { sql: string; prepare: number }, expected: { rows: number; fields?: number }, values?: number[]): Promise<void> {
  const options = { sql: entry.sql, rowsAsArray: true }
  for (const method of ['query', 'execute', 'prepared']) {
    const [rows, fields] = method === 'prepared' ? await statement.execute(values ?? []) : method === 'query' ? await conn.query(options, values) : await conn.execute(options, values)
    assert.deepEqual(rows, method === 'prepared' ? objectRows(ROWS[expected.rows]!, entry.prepare) : ROWS[expected.rows], `${entry.sql}/${values}/${method}: rows`)
    // ORDER BY NULL copying/sort admission remains separate; expectations are native only.
    if (expected.fields !== undefined) assert.deepEqual(fieldsOf(fields), FIELDS[expected.fields], `${entry.sql}/${values}/${method}: fields`)
    assert.deepEqual((await conn.query('SHOW WARNINGS'))[0], [], `${entry.sql}/${values}/${method}: warnings`)
  }
}

test('bounded DISTINCT retains native field metadata across key shapes, cardinalities and LIMIT/OFFSET', async () => {
  await withSchema('bounded81', async (conn) => {
    for (const [table, definition] of DEFS) {
      await conn.query(`CREATE TABLE ${table}(${definition}) STATS_AUTO_RECALC=0`)
      for (const count of [0, 4, 256]) {
        await conn.query(`DELETE FROM ${table}`)
        if (count > 0) {
          const values = Array.from({ length: count }, (_, i) => {
            const x = table === 'nullable' && i < 2 ? 'NULL' : ['unique_key', 'composite', 'nullable'].includes(table!) ? i + 1 : i % 8 === 0 ? 'NULL' : i % 8
            return `(${table === 'primary_key' ? `${i + 1},` : ''}${x},'v${i % 4}')`
          }).join(',')
          await conn.query(`INSERT INTO ${table} VALUES ${values}`)
        }
        await conn.query(`ANALYZE TABLE ${table}`)
        for (const entry of CASES.filter((c) => c.table === table && c.count === count)) {
          const options = { sql: entry.sql, rowsAsArray: true }
          const statement = await conn.prepare(options)
          try {
            const columns = (statement as unknown as { statement: { columns: mysql.FieldPacket[] } }).statement.columns
            assert.deepEqual(fieldsOf(columns), FIELDS[entry.prepare], `${entry.sql}: prepare`)
            await execution(conn, statement, entry, entry)
            if (entry.plan !== undefined) {
              const [rows] = await conn.query<mysql.RowDataPacket[]>('EXPLAIN FORMAT=TREE ' + entry.sql)
              assert.equal(planSkeleton(rows[0]!.EXPLAIN), entry.plan, `${entry.sql}: plan`)
            }
          } finally { await statement.close(); conn.unprepare(options) }
        }
      }
    }
  })
})

test('bounded copied fields remain fresh for retained statements with changing parameters and writes', async () => {
  const bounds = [[0, 0], [0, 1], [1, 0], [1, 10], [2, 1]]
  await withSchema('bounded81_fresh', async (conn) => {
    for (const [table, definition, values] of FRESH_DEFS) {
      await conn.query(`CREATE TABLE ${table}(${definition}) STATS_AUTO_RECALC=0`)
      await conn.query(`INSERT INTO ${table} VALUES ${values}`)
      await conn.query(`ANALYZE TABLE ${table}`)
      for (const entry of FRESH_CASES.filter((c) => c.table === table)) {
        const options = { sql: entry.sql, rowsAsArray: true }
        const statement = await conn.prepare(options)
        try {
          const columns = (statement as unknown as { statement: { columns: mysql.FieldPacket[] } }).statement.columns
          assert.deepEqual(fieldsOf(columns), FIELDS[entry.prepare], `${entry.sql}: prepare`)
          for (const state of [0, 1, 2, 3]) {
            if (state === 1) await conn.query(`UPDATE ${table} SET y=CONCAT('z',y)`)
            if (state === 2) await conn.query(`DELETE FROM ${table}`)
            if (state === 3) { await conn.query(`DELETE FROM ${table}`); await conn.query(`INSERT INTO ${table} VALUES ${values}`) }
            for (const [i, parameters] of bounds.entries()) await execution(conn, statement, entry, entry.states[state]![i]!, parameters)
          }
        } finally { await statement.close(); conn.unprepare(options) }
      }
    }
  })
})
